code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != background]
    if not points:
        return out
    cr = sum(r for r, c in points) / len(points)
    cc = sum(c for r, c in points) / len(points)
    for color in set(grid[r][c] for r, c in points):
        cells = {(r, c) for r, c in points if grid[r][c] == color}
        # Diagonal two-pixel-or-longer runs; extend the more outward endpoint.
        for dr, dc in ((1, 1), (1, -1)):
            for r, c in list(cells):
                if (r-dr, c-dc) in cells:
                    continue
                run = [(r, c)]
                rr, cc2 = r+dr, c+dc
                while (rr, cc2) in cells:
                    run.append((rr, cc2))
                    rr += dr; cc2 += dc
                if len(run) < 2:
                    continue
                a, b = run[0], run[-1]
                da = (a[0]-cr)**2 + (a[1]-cc)**2
                db = (b[0]-cr)**2 + (b[1]-cc)**2
                if da > db:
                    r0, c0 = a
                    sr, sc = -dr, -dc
                else:
                    r0, c0 = b
                    sr, sc = dr, dc
                rr, cc2 = r0+sr, c0+sc
                while 0 <= rr < h and 0 <= cc2 < w and out[rr][cc2] == background:
                    out[rr][cc2] = color
                    rr += sr; cc2 += sc
    return out
'''
